from __future__ import annotations

from typing import Any


def parse_text_table(text: str) -> list[dict[str, Any]]:
    """Parse pipe-delimited text table rows into dictionaries.

    The function is deliberately dependency-free so it can run in a sandboxed
    runtime. It ignores separator rows and returns an empty list when no valid
    header/data rows are present.
    """
    lines = [line.strip() for line in str(text or "").splitlines() if "|" in line]
    rows: list[list[str]] = []
    for line in lines:
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        if len(cells) < 2:
            continue
        if all(cell and set(cell) <= set("-: ") for cell in cells):
            continue
        rows.append(cells)
    if len(rows) < 2:
        return []
    header = rows[0]
    output: list[dict[str, Any]] = []
    for row in rows[1:]:
        item: dict[str, Any] = {}
        for index, name in enumerate(header):
            key = name or f"column_{index + 1}"
            item[key] = row[index] if index < len(row) else ""
        output.append(item)
    return output


def run(input_data: Any = None, **kwargs: Any) -> dict[str, Any]:
    if isinstance(input_data, dict):
        text = input_data.get("text") or input_data.get("content") or ""
    elif input_data is None:
        text = kwargs.get("text") or kwargs.get("content") or ""
    else:
        text = str(input_data)
    rows = parse_text_table(str(text or ""))
    return {
        "status": "completed",
        "row_count": len(rows),
        "rows": rows,
    }

from __future__ import annotations

import base64
import io
import zipfile
import xml.etree.ElementTree as ET
from pathlib import Path
from typing import Any


def _read_bytes(input_data: dict[str, Any]) -> bytes:
    if input_data.get("bytes_base64"):
        return base64.b64decode(str(input_data.get("bytes_base64")))
    if input_data.get("docx_base64"):
        return base64.b64decode(str(input_data.get("docx_base64")))
    path_value = input_data.get("path") or input_data.get("file_path")
    if path_value:
        return Path(str(path_value)).read_bytes()
    raw = input_data.get("bytes")
    if isinstance(raw, bytes):
        return raw
    raise ValueError("DOCX input requires path, file_path, bytes, bytes_base64, or docx_base64.")


def extract_docx_text_from_bytes(data: bytes) -> str:
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        xml_bytes = archive.read("word/document.xml")
    root = ET.fromstring(xml_bytes)
    namespace = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
    paragraphs: list[str] = []
    for paragraph in root.iter(namespace + "p"):
        parts: list[str] = []
        for node in paragraph.iter(namespace + "t"):
            if node.text:
                parts.append(node.text)
        if parts:
            paragraphs.append("".join(parts))
    return "\n".join(paragraphs).strip()


def run(input_data: Any = None, **kwargs: Any) -> dict[str, Any]:
    payload = input_data if isinstance(input_data, dict) else {}
    payload = {**payload, **kwargs}
    try:
        data = _read_bytes(payload)
        text = extract_docx_text_from_bytes(data)
        paragraphs = [line for line in text.splitlines() if line.strip()]
        return {
            "status": "completed",
            "text": text,
            "paragraph_count": len(paragraphs),
            "character_count": len(text),
        }
    except Exception as exc:
        return {
            "status": "failed",
            "error": {"type": exc.__class__.__name__, "message": str(exc)},
            "text": "",
            "paragraph_count": 0,
            "character_count": 0,
        }

from __future__ import annotations

from typing import Any


def run(input_data: Any = None, **kwargs: Any) -> dict[str, Any]:
    payload = input_data if isinstance(input_data, dict) else {}
    payload = {**payload, **kwargs}
    runtime = payload.get('_runtime') if isinstance(payload.get('_runtime'), dict) else {}
    connection = runtime.get('connection') if isinstance(runtime.get('connection'), dict) else {}
    secrets = runtime.get('secrets') if isinstance(runtime.get('secrets'), dict) else {}
    configured = bool(connection)
    secret_available = bool(secrets)
    return {
        'status': 'completed' if configured and secret_available else 'failed',
        'data': {
            'configured': configured,
            'secret_available': secret_available,
            'received_keys': sorted([str(k) for k in payload.keys() if k != '_runtime']),
            'connection_keys': sorted([str(k) for k in connection.keys()]),
            'secret_keys': sorted([str(k) for k in secrets.keys()]),
        },
        'configured': configured,
        'secret_available': secret_available,
    }
